mc("mcq10", ("औसत की मुख्य सीमा यह है कि यह:", "સરેરાશની મુખ્ય મર્યાદા એ છે કે તે:"), ("एक ही औसत वाले दो देशों में बँटवारा बहुत अलग हो सकता है।", "એક જ સરેરાશવાળા બે દેશોમાં વહેંચણી ઘણી જુદી હોઈ શકે."),
   {"hides disparities": (("असमानताएँ छिपाता है", "અસમાનતાઓ છુપાવે છે"), OK), "is hard to calculate": (("निकालना कठिन है", "ગણવી મુશ્કેલ છે"), ("इसे निकालना आसान है।", "તે ગણવી સરળ છે.")), "always overstates income": (("हमेशा आय बढ़ाकर दिखाता है", "હંમેશાં આવક વધારીને બતાવે છે"), ("हमेशा नहीं।", "હંમેશાં નહિ.")), "cannot be used for comparison": (("तुलना में इस्तेमाल नहीं हो सकता", "સરખામણીમાં વાપરી શકાય નહિ"), ("यह तुलना के लिए उपयोगी है।", "તે સરખામણી માટે ઉપયોગી છે."))})
